CREATE POLICY "driver docs upload own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'driver-docs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "driver docs read own or admin" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'driver-docs' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(),'admin')));